code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    keep = {bg}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); comp = []
            while stack:
                y, x = stack.pop(); comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(comp) >= 4:
                keep.add(color)
    return [[v if v in keep else bg for v in row] for row in grid]
